const en=()=>document.documentElement.lang.startsWith('en');
const t=(zh,enText)=>en()?enText:zh;
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m6 9 6 6 6-6"/></svg>';
const label=(zh,eng)=>`<span data-site-zh="${zh}" data-site-en="${eng}">${t(zh,eng)}</span>`;
const mobile=document.querySelector('.mn-links');
if(mobile)mobile.innerHTML=`<a href="./">${label('首页','Home')}<i>↗</i></a><a href="./works-center.html">${label('作品中心','Works center')}<i>↗</i></a><details class="nav-group"><summary><a href="./how-to.html">${label('如何使用','How to use')}</a>${arrow}</summary><div class="nav-submenu"><a href="./how-to.html#steps">${label('使用教程','Tutorial')}</a><button data-nav-info="ai">${label('AI 说明','AI guide')}</button></div></details><details class="nav-group"><summary><a href="./about.html">${label('关于我们','About us')}</a>${arrow}</summary><div class="nav-submenu"><button data-nav-contact>${label('联系我们','Contact us')}</button><button data-nav-info="partners">${label('招商加盟','Partner with us')}</button><a href="./print-locations.html">${label('查找设备','Find a printer')}</a></div></details>`;
mobile?.querySelectorAll('i').forEach(i=>i.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 19 19 5M5 5h14v14"/></svg>');
function closeDrawer(){const d=document.querySelector('.mn-drawer');if(d?.open){d.close();document.documentElement.classList.remove('mn-menu-open');document.querySelector('.mn-open')?.setAttribute('aria-expanded','false');}}
mobile?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeDrawer));
const groups=[...document.querySelectorAll('.nav-group')];groups.forEach(g=>g.addEventListener('toggle',()=>{if(g.open)groups.forEach(other=>{if(other!==g)other.open=false;});}));
document.addEventListener('click',e=>{groups.filter(g=>!g.contains(e.target)).forEach(g=>g.open=false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')groups.forEach(g=>g.open=false);});
function showInfo(kind){closeDrawer();groups.forEach(g=>g.open=false);const d=document.createElement('dialog');d.className='nav-info-dialog';const titles={tutorial:t('使用教程','How to create your case'),ai:t('AI 创作说明','Your photo. A little AI.'),partners:t('招商加盟','Let’s create together.')};let body='';
if(kind==='tutorial')body=`<video controls playsinline preload="metadata" poster="./assets/tutorial-poster.jpg"><source src="./assets/tutorial-demo.mp4" type="video/mp4"><track src="./assets/tutorial-en.vtt" kind="captions" srclang="en" label="English"></video><p>${t('选择机型与颜色，添加底图、贴图和文字。确认设计后，再选择设备打印或快递到家。','Choose your phone and color. Add a background, stickers and words. Review your case, then choose nearby printing or home delivery.')}</p>`;
if(kind==='ai')body=`<img src="./assets/ai-creation-cover.webp" alt=""><p>${t('先上传照片，再选择创作分类与风格，生成后可以对比效果。使用 AI 图作为手机壳底图，继续添加贴图与文字。','Upload a photo, choose a category and style, then generate and compare your result. Use the AI image as your case background and add stickers or text.')}</p>`;
if(kind==='partners')body=`<p>${t('想把个性定制带到你的门店？欢迎与 POPOMO 联系，交流设备合作与加盟意向。','Bring personal creations to your store. Connect with POPOMO to discuss printing-device partnerships and collaboration.')}</p><button class="primary" data-partner-contact>${t('联系团队','Contact our team')} ↗</button>`;
d.innerHTML=`<header><h2>${titles[kind]}</h2><button class="nav-info-close" aria-label="${t('关闭','Close')}">×</button></header>${body}`;document.body.append(d);d.querySelector('.nav-info-close').onclick=()=>d.close();d.querySelector('[data-partner-contact]')?.addEventListener('click',()=>{d.close();document.querySelector('#aimo-contact-dialog')?.showModal();});d.addEventListener('close',()=>{d.querySelector('video')?.pause();d.remove();},{once:true});d.showModal();}
document.querySelectorAll('[data-nav-info]').forEach(b=>b.addEventListener('click',()=>showInfo(b.dataset.navInfo)));
document.querySelectorAll('[data-nav-contact]').forEach(b=>b.addEventListener('click',()=>{closeDrawer();groups.forEach(g=>g.open=false);document.querySelector('#aimo-contact-dialog')?.showModal();}));
function sync(){document.querySelectorAll('.site-nav [data-site-en],.mn-links [data-site-en]').forEach(e=>e.textContent=e.dataset[en()?'siteEn':'siteZh']);}
new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});sync();
